desabafo.proto (Servidor A — Desabafos)chat.proto (Servidor A — Sala ao Vivo)reacoes.proto (Servidor B — Reações) <pre><code>syntax = "proto3";

package desabafo;
option go_package = "gen/desabafo;desabafo";

service Feed {
    rpc PostDesabafo(RascunhoDesabafo) returns (Desabafo);
    rpc GetFeed(FeedRequest) returns (stream Desabafo);
}

message FeedRequest {
    int64 quant =1;
}

message RascunhoDesabafo {
    string texto=1;
}

message Desabafo {
    string texto=1;
    int32 id =2;
    int64 created_at = 3;
}
</code></pre> <pre><code>syntax = "proto3";

package chat;
option go_package = "gen/chat;chat";

service ChatService {
  // Bidirectional streaming: client and server both send messages freely.
  rpc Chat(stream ChatMessage) returns (stream ChatMessage);
}

message ChatMessage {
    string message_id = 1;
    string text = 2;
    string room_id =3;
    string sender_nickname=4;
    int64 send_at =5;
}
</code></pre> <pre><code>syntax = "proto3";

package reacoes;

option java_multiple_files = true;

